    @Test
    void cupomInvalidoEhDetectado() {
        ResumoRequest req = new ResumoRequest(
                List.of(camiseta()), "ECONOMICA", "NAOEXISTE", "PIX", null, "BRONZE", "SUDESTE");

        assertThatThrownBy(() -> service.calcular(req))
